const raw = $input.first().json;
const body = raw.body || raw;

let phone = body.phone || body.chatId || body.from || '';
phone = String(phone).replace('@c.us', '').replace('@s.whatsapp.net', '');

// Detect group messages
const chatId = String(body.chatId || '');
const isGroup = body.isGroup === true ||
                chatId.includes('@g.us') ||
                String(phone).includes('-group') ||
                String(phone).includes('@g.us');

const isFromMe = body.fromMe === true;
const isStatus = phone === 'status' || phone === '';

// Filter out invalid messages early
if (isGroup || isFromMe || isStatus || !phone) {
  return [];
}

let messageType = 'text';
let messageContent = '';
let mediaUrl = '';
let fileName = '';

if (body.audio) {
  messageType = 'audio';
  mediaUrl = body.audio.audioUrl;
  messageContent = '[ÁUDIO - AGUARDANDO TRANSCRIÇÃO]';
} else if (body.image) {
  messageType = 'image';
  mediaUrl = body.image.imageUrl;
  messageContent = body.image.caption || '[Imagem sem legenda]';
} else if (body.video) {
  messageType = 'video';
  mediaUrl = body.video.videoUrl;
  messageContent = body.video.caption || '[Vídeo]';
} else if (body.document) {
  messageType = 'document';
  mediaUrl = body.document.documentUrl;
  fileName = body.document.fileName || 'documento';
  messageContent = `[Documento: ${fileName}]`;
} else if (body.sticker) {
  messageType = 'sticker';
  messageContent = '[Sticker]';
} else if (body.listResponseMessage) {
  messageType = 'list_response';
  messageContent = body.listResponseMessage.title || body.listResponseMessage.singleSelectReply?.selectedRowId || '';
} else if (body.buttonsResponseMessage) {
  messageType = 'button_response';
  messageContent = body.buttonsResponseMessage.selectedButtonId || body.buttonsResponseMessage.selectedDisplayText || '';
} else if (body.text) {
  messageType = 'text';
  if (typeof body.text === 'object') {
    messageContent = body.text.message || '';
  } else {
    messageContent = String(body.text);
  }
} else {
  messageType = 'unknown';
  messageContent = JSON.stringify(body).substring(0, 200);
}

return [{
  json: {
    phone, message_type: messageType, message_content: messageContent,
    media_url: mediaUrl, file_name: fileName,
    raw_timestamp: body.timestamp || Date.now()
  }
}];

function normalizePhone(rawPhone) {
  if (!rawPhone) return null;
  let phone = rawPhone.toString().trim().replace(/[^\d+]/g, '');
  if (phone.startsWith('+353')) return phone;
  if (phone.startsWith('353')) return `+${phone}`;
  if (phone.startsWith('08')) return `+353${phone.substring(1)}`;
  if (phone.length === 9 && phone.startsWith('8')) return `+353${phone}`;
  if (phone.startsWith('+55')) return phone;
  if (phone.startsWith('55') && phone.length >= 12) return `+${phone}`;
  return phone.startsWith('+') ? phone : `+${phone}`;
}
const input = $input.first().json;
return [{ json: { ...input, original_phone: input.phone, normalized_phone: normalizePhone(input.phone) } }];

const input = $input.first().json;
const t = input.message_type;
let texto = '';

if (t === 'text' || t === 'button_response' || t === 'list_response') {
  texto = input.message_content;
} else if (t === 'image') {
  texto = '[IMAGEM] ' + input.message_content + ' ' + input.media_url;
} else if (t === 'video') {
  texto = '[VÍDEO] ' + input.media_url;
} else if (t === 'document') {
  texto = '[DOCUMENTO] ' + input.file_name + ' ' + input.media_url;
} else if (t === 'audio') {
  texto = '__AUDIO__';
} else {
  texto = input.message_content || '[mensagem nao suportada]';
}

return [{ json: { ...input, texto, needs_transcription: t === 'audio' } }];

const transcribed = $json.text || '';
const context = $('Normalize Phone').first().json;
return [{ json: { ...context, texto: transcribed, needs_transcription: false } }];

const raw = $('Pull Messages').first().json.mensagens || '';
const currentTexto = $('Classify Message').first().json.texto || '';
const context = $('Normalize Phone').first().json;

// Parse the Redis list string: "['msg1', 'msg2', ...]"
let messages = [];
const rawStr = String(raw);
if (rawStr.startsWith('[')) {
  const trimmed = rawStr.slice(1, -1).trim();
  if (trimmed.length > 0) {
    messages = trimmed.split("', '").map(s => s.replace(/^'/, '').replace(/'$/, '').trim());
  }
} else if (rawStr.length > 0) {
  messages = [rawStr];
}

if (messages.length === 0) {
  return []; // No messages in Redis
}

// For single message, always process it
if (messages.length === 1) {
  return [{
    json: {
      normalized_phone: context.normalized_phone,
      original_phone: context.original_phone,
      merged_message: messages[0],
      message_count: 1,
      raw_timestamp: context.raw_timestamp
    }
  }];
}

// For multiple messages (batch), only the LAST execution should process
const lastMsg = messages[messages.length - 1];
const snippet = currentTexto.substring(0, 40);

if (snippet && lastMsg.includes(snippet)) {
  return [{
    json: {
      normalized_phone: context.normalized_phone,
      original_phone: context.original_phone,
      merged_message: messages.join('\n'),
      message_count: messages.length,
      raw_timestamp: context.raw_timestamp
    }
  }];
}

// Not the last message in the batch — skip
return [];

const items = $input.all();
const context = $('Dedup & Merge').first().json;

// Check for error objects from onError: continueRegularOutput
const firstItem = items.length > 0 ? items[0].json : {};
const hasError = firstItem.error || firstItem.errorMessage;
const hasLeadId = firstItem.lead_id && firstItem.lead_id.toString().trim() !== '';

if (items.length === 0 || hasError || !hasLeadId) {
  // No lead found or error — pass empty lead_id so Is New Lead? routes to true
  return [{ json: { lead_id: '', phone: context.normalized_phone } }];
}

// Lead found — pass through
return items;

const msg = $('Dedup & Merge').first().json;
const phone = msg.normalized_phone;
const leadId = 'BR-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.random().toString(36).substring(2, 8).toUpperCase();
return [{ json: { lead_id: leadId, name: 'WhatsApp Lead', email: '', phone: phone, source: 'whatsapp', nationality: '', visa_type: '', english_level: '', preferred_date: '', stage: 'new_lead', score: 25, priority: 'medium', qualification_notes: 'Auto-registered via WhatsApp', created_at: new Date().toISOString(), updated_at: new Date().toISOString(), next_follow_up: '', notes: 'First message: ' + (msg.merged_message || '').substring(0, 200), utm_source: 'whatsapp_organic', utm_campaign: '', lost_reason: '', referred_by: '' } }];

const msgs = $('Pull Messages').first().json.mensagens || [];
const context = $('Normalize Phone').first().json;
const leadData = $('Check Lead Exists').first().json;
const mergedMsg = $('Dedup & Merge').first().json.merged_message || '';
const isNewLead = !leadData.lead_id;
return [{ json: { lead_id: leadData.lead_id || `lead_${Date.now()}`, phone: context.normalized_phone, name: leadData.lead_name || leadData.name || 'Novo Lead', stage: leadData.lead_stage || leadData.stage || 'new_lead', score: leadData.lead_score || leadData.score || 0, message: mergedMsg, message_type: 'text', is_new_lead: isNewLead, channel: 'whatsapp' } }];

const input = $input.first().json;
const phone = input.phone;
const instanceId = $env.ZAPI_INSTANCE_ID;
const token = $env.ZAPI_TOKEN;
const clientToken = $env.ZAPI_CLIENT_TOKEN;
const baseUrl = `https://api.z-api.io/instances/${instanceId}/token/${token}`;

let endpoint = '';
let body = {};

switch (input.type || 'text') {
  case 'text':
    endpoint = '/send-text';
    body = { phone, message: input.message, delayTyping: 8 };
    break;
  case 'image':
    endpoint = '/send-image';
    body = { phone, image: input.media_url, caption: input.message || '', delayTyping: 5 };
    break;
  case 'document':
    endpoint = '/send-document/pdf';
    body = { phone, document: input.media_url, fileName: input.file_name || 'documento.pdf', caption: input.message || '', delayTyping: 3 };
    break;
  case 'video':
    endpoint = '/send-video';
    body = { phone, video: input.media_url, caption: input.message || '', delayTyping: 5 };
    break;
  case 'audio':
    endpoint = '/send-audio';
    body = { phone, audio: input.audio_url, delayTyping: 8 };
    break;
  default:
    endpoint = '/send-text';
    body = { phone, message: input.message, delayTyping: 8 };
}

return [{ json: { url: baseUrl + endpoint, body, phone, type: input.type || 'text', clientToken } }];
